INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-active-directory-account-lockout--00-identity-account-lockout','kb-active-directory-account-lockout','0','Identity: Account lockout','Portfolio knowledge article. Synthetic lab context; technician validation required.','cb89be873cdd1208daeb16d914bc4437f11e02e2d51f907d4b797e94b10a88c4');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-active-directory-account-lockout--01-symptoms','kb-active-directory-account-lockout','1','Symptoms','- active directory account locked repeated failed domain logon
- domain user locked out after password change
- windows sign in account lockout on domain controller
- directory authentication account disabled or locked
- cannot logon domain account says locked','d377fbdc7513ca1371671eba16892f53ee8059cd6f898206eb492fc569dc1a6c');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-active-directory-account-lockout--02-working-hypothesis','kb-active-directory-account-lockout','2','Working hypothesis','Directory authentication is blocked by a lockout; stale credentials are one possible source.','1c249b2a6d27de86e0a2dd1f7646e829261fd9124b322428586811defd4a0c26');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-active-directory-account-lockout--03-troubleshooting','kb-active-directory-account-lockout','3','Troubleshooting','1. Confirm user identity using the approved verification procedure; never request a password.
2. Ask the directory team to inspect lockout events and the originating device.
3. Check for stored credentials in scheduled tasks, mobile mail and mapped drives.
4. After identity verification, request an authorized unlock and update stale credentials.
5. Validate a fresh sign-in and monitor for repeated lockouts; escalate suspicious activity.','e6fd89fc9336c959bec3ec83b7e1cafc81a33d4b1adee28b942cf06e20dd598b');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-active-directory-account-lockout--04-escalation-and-closure','kb-active-directory-account-lockout','4','Escalation and closure','Escalate when scope exceeds authorization, symptoms persist, or security indicators appear. Close only after user validation. Record evidence and outcome.','970b3d0e6ec4732b76d4634cfd6a7035ef379c06587f29a0cd10c4af904f7150');
