INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-network-dns-troubleshooting--01-symptoms','kb-network-dns-troubleshooting','1','Symptoms','- dns server not responding hostname lookup failure
- internal website name resolution fails but ip works
- cannot resolve intranet hostname dns record
- dns nxdomain on company network
- network connectivity dns lookup timeout','813a457e6afe4b46c8f5c561e1a25b8c2355eddeb371f8d74f8977e7fdd161c6');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-network-dns-troubleshooting--02-working-hypothesis','kb-network-dns-troubleshooting','2','Working hypothesis','An incorrect DNS server, stale cache or missing record may prevent name resolution.','a2dc7824626e8722c54ca9300a24b1f5fc65cc0c726d3510c8cc49ac63e99ee2');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-network-dns-troubleshooting--03-troubleshooting','kb-network-dns-troubleshooting','3','Troubleshooting','1. Confirm scope and record the affected hostname and exact error.
2. Compare connectivity by approved IP and hostname; ping failure alone does not prove an outage.
3. Inspect adapter and DNS configuration; use Resolve-DnsName against the configured resolver.
4. Compare with a working device; do not replace corporate DNS with public resolvers.
5. Consider an approved cache flush only when evidence supports it; escalate authoritative record or resolver faults.','4daceb94fc9a1423d3dbd2b1a3b6a959568a61a2cfb5b4bdd96fbe44612427c0');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-network-dns-troubleshooting--04-escalation-and-closure','kb-network-dns-troubleshooting','4','Escalation and closure','Escalate when scope exceeds authorization, symptoms persist, or security indicators appear. Close only after user validation. Record evidence and outcome.','970b3d0e6ec4732b76d4634cfd6a7035ef379c06587f29a0cd10c4af904f7150');
