INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-business-application-erp--02-working-hypothesis','kb-business-application-erp','2','Working hypothesis','The ERP service, backend connectivity or application authorization may be failing.','4e91c0f2f493f72a263605c46c3e7f5a200076bb10a7a997014dafe20f5b5dd7');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-business-application-erp--03-troubleshooting','kb-business-application-erp','3','Troubleshooting','1. Capture the application error, timestamp and affected business workflow.
2. Confirm whether the issue affects multiple users and check the service status.
3. Test the approved application endpoint without collecting business records.
4. Gather sanitized correlation IDs and compare recent approved deployments.
5. Escalate to application support with impact and evidence; do not restart the database or change production records.','300c06d862a2d69271bd6fe5a3eb8057d1f16885582aa2990fa1aa218b70f038');
