INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-microsoft365-outlook-authentication--01-symptoms','kb-microsoft365-outlook-authentication','1','Symptoms','- outlook keeps asking password microsoft 365 login
- microsoft 365 mfa authentication sign in error
- outlook authentication loop office token expired
- office 365 mailbox cannot sign in
- outlook web access works desktop sign in fails','e14056157307e133cdb60953b6ca5559b822b13467c51583e838a6309a2e38a7');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-microsoft365-outlook-authentication--02-working-hypothesis','kb-microsoft365-outlook-authentication','2','Working hypothesis','An expired sign-in session or a tenant authentication policy may be interrupting Outlook access.','c1edf3606b08f927fbb52bb59ed50fe43a01354ce1208f8c88f56cb816ef07f7');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-microsoft365-outlook-authentication--03-troubleshooting','kb-microsoft365-outlook-authentication','3','Troubleshooting','1. Capture the error, sign-in time and whether Outlook on the web works.
2. Check Microsoft 365 service health through the authorized administrator.
3. Validate account, license and MFA status through approved support channels.
4. Try an approved sign-out and sign-in; preserve drafts and avoid deleting profiles prematurely.
5. Escalate Conditional Access or repeated authentication failures with correlation IDs, without tokens or passwords.','eb2d3d1a6294dc37d9d87a62695f5bb7d6dc2b6513e61ca84836a5a97864534c');
