INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-access-shared-folder--01-symptoms','kb-access-shared-folder','1','Symptoms','- mapped network drive access denied shared folder
- smb file share permission denied unc path
- network drive disconnected file server access
- shared folder ntfs permissions cannot open
- mapped drive missing after login share access','87e84f1647f4f9cf36fac49986970e13e7a2e4d061e58815d9547956c535d0df');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-access-shared-folder--02-working-hypothesis','kb-access-shared-folder','2','Working hypothesis','An SMB session, group membership or share/NTFS permission mismatch may deny access.','e7f420a7511dcff0c4b9809b004545a74b92b0f83876a95a0f41167673b100d4');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-access-shared-folder--03-troubleshooting','kb-access-shared-folder','3','Troubleshooting','1. Capture the UNC path and error; confirm VPN or local network connectivity.
2. Check name resolution and connectivity to the approved file server.
3. Compare effective share and NTFS permissions with the documented entitlement.
4. Check recent group changes and reconnect the session after an approved sign-in refresh.
5. Request data-owner authorization for permission changes; never grant broad access as a shortcut.','c975fffe5ee20dd843f3f2fbccd5b2726784c00bde3b53fbf821cf663745c518');
