INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-hardware-printing--01-symptoms','kb-hardware-printing','1','Symptoms','- printer offline cannot print documents queue stuck
- print spooler service stopped jobs pending
- network printer offline print queue error
- printing fails printer unavailable
- documents stuck in spooler printing queue','d9261d46bd350c64e6ecd312e01eaf1d5eaa22614b94b1b2902172584397bb3c');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-hardware-printing--02-working-hypothesis','kb-hardware-printing','2','Working hypothesis','The printer connection, queue or spooler may be unavailable; confirm which layer is failing.','0490eec522c36340d2338eb3017a1eb25806043f7cda14f56414ee3eab1d7bb1');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-hardware-printing--03-troubleshooting','kb-hardware-printing','3','Troubleshooting','1. Check printer power, display errors, paper and network connection.
2. Confirm whether one user or the entire printer queue is affected.
3. Check the configured printer port and queue status before changing settings.
4. Inspect Print Spooler status; record pending jobs before proposing a restart.
5. If approved, restart the spooler during an agreed window and print a test page; escalate hardware faults.','ab76ca84255517bf96c0a9831ba370611687fa8b63459e5b68b36b7494156aac');
