INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-software-general-incidents--01-symptoms','kb-software-general-incidents','1','Symptoms','- desktop application crashes or will not launch
- software error after an approved update
- application freezes for one user
- general program installation or runtime failure','388e806cf9a39bf5c904533a7f2b86933f2dd188b1516ffe893a73cf6694bd4f');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-software-general-incidents--02-working-hypothesis','kb-software-general-incidents','2','Working hypothesis','A local application state, dependency, configuration, or recent approved change may be responsible.','25ffbbf79ac7ecf464a430f9a48971251154a32a73cf3e5f1a277dde4b505f06');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-software-general-incidents--03-troubleshooting','kb-software-general-incidents','3','Troubleshooting','1. Capture the exact error, application version, start time, and affected scope.
2. Confirm whether the same approved application works for another synthetic user or workstation.
3. Review recent approved changes and vendor support status without downloading unapproved tools.
4. Preserve user files and logs approved for support before proposing repair or reinstallation.
5. Validate recovery with the user; escalate repeat crashes, security indicators, or unsupported software.','db8ef91ae595f85c5cd610f9237fcbc20f90f0c0ad79613a70a922702cb1493a');
