INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-network-vpn-troubleshooting--01-symptoms','kb-network-vpn-troubleshooting','1','Symptoms','- vpn connection failed after changing password
- remote access vpn tunnel authentication rejected
- vpn client cannot connect gateway timeout
- vpn disconnect remote worker authentication error
- unable to establish corporate vpn tunnel','a85c6026d3ba60ded09cd706a9314b28446d7e062ecd3ffbf9b73d43a6c01a0c');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-network-vpn-troubleshooting--02-working-hypothesis','kb-network-vpn-troubleshooting','2','Working hypothesis','Saved VPN credentials or a client authentication state may be stale after a password change.','5ca6f3a1364311eb0e6e0ed5f6107dd9277cdb34e195a979593d12c47252055c');
INSERT INTO knowledge_chunks(chunk_id,document_id,ordinal,heading,content,content_hash) VALUES('kb-network-vpn-troubleshooting--03-troubleshooting','kb-network-vpn-troubleshooting','3','Troubleshooting','1. Confirm internet access before troubleshooting the VPN tunnel.
2. Capture the VPN error and time; verify the approved gateway and service status.
3. Validate account status and MFA through approved processes without sharing credentials.
4. Re-enter updated credentials in the approved client; do not disable MFA or certificate validation.
5. Reconnect and validate access to an approved internal resource; escalate persistent gateway failures.','833bcb7fb7101d2bdc67545b6317a45e5239fc005a6fc9273ee4d84139685a0d');
